style.css:
@-moz-document domain("roblox.com") {
/* ── Fundo global ── */
  html, body {
    background-image: url("https://i.imgur.com/6p0V26N.jpeg") !important;
    background-size: cover !important;
    background-position: center center !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
  }

  /* ── Remove fundos opacos que tapam a imagem ── */
  .rbx-body,
  #rbx-body,
  .ng-scope,
  .main-content,
  #react-app,
  #root,
  .page-container,
  .container-main {
    background: transparent !important;
    background-color: transparent !important;
  }

  /* ── Navbar: leve transparência pra não sufocar o fundo ── */
  #navigation,
  .rbx-navbar,
  .navbar,
  nav,
  [class*="navigation"],
  [class*="navbar"] {
    background-color: rgba(0, 0, 0, 0.55) !important;
    backdrop-filter: blur(8px) !important;
    -webkit-backdrop-filter: blur(8px) !important;
  }

  /* ── Sidebar esquerda ── */
  .rbx-left-col,
  .left-col,
  [class*="left-col"],
  [class*="sidebar"] {
    background-color: rgba(0, 0, 0, 0.45) !important;
    backdrop-filter: blur(6px) !important;
    -webkit-backdrop-filter: blur(6px) !important;
  }

  /* ── Cards e painéis de conteúdo ── */
  .card,
  .section,
  .container-list-extended,
  .game-card-container,
  .item-card-container,
  [class*="card"],
  [class*="panel"],
  [class*="tile"] {
    background-color: rgba(20, 20, 30, 0.60) !important;
    backdrop-filter: blur(4px) !important;
    -webkit-backdrop-filter: blur(4px) !important;
    border: 1px solid rgba(255, 255, 255, 0.08) !important;
    border-radius: 10px !important;
  }

  /* ── Modais / popups ── */
  .modal-content,
  .modal-body,
  [class*="modal"] {
    background-color: rgba(15, 15, 25, 0.88) !important;
    backdrop-filter: blur(12px) !important;
    -webkit-backdrop-filter: blur(12px) !important;
  }

  /* ── Footer ── */
  footer,
  .rbx-footer,
  [class*="footer"] {
    background-color: rgba(0, 0, 0, 0.65) !important;
    backdrop-filter: blur(8px) !important;
    -webkit-backdrop-filter: blur(8px) !important;
  }

  /* ── Textos legíveis sobre o fundo ── */
  body, p, span, a, li, h1, h2, h3, h4, h5, label {
    text-shadow: 0 1px 3px rgba(0, 0, 0, 0.7) !important;
  }

  /* ── Inputs e campos de busca ── */
  input, textarea, select {
    background-color: rgba(0, 0, 0, 0.5) !important;
    border: 1px solid rgba(255, 255, 255, 0.15) !important;
    color: #fff !important;
  }
}
